<?php use App\Support\App;$u=App::requireAuth();$db=App::db();$q=$db->prepare('SELECT COUNT(*) total,SUM(status="processing") processing FROM orders WHERE user_id=?');$q->execute([$u['id']]);$s=$q->fetch();$title='Dashboard';require __DIR__.'/../layouts/head.php';?><div class="flex"><?php require __DIR__.'/../components/sidebar.php';?><main class="p-8 flex-1"><h1 class="text-2xl font-semibold">Dashboard</h1><div class="grid md:grid-cols-3 gap-4 mt-8"><?php foreach([['Balance','Rp'.number_format($u['balance'],0,',','.')],['Total orders',$s['total']??0],['Processing',$s['processing']??0]] as $x):?><div class="saas-card p-5"><p class="text-zinc-500"><?=$x[0]?></p><b class="text-2xl"><?=$x[1]?></b></div><?php endforeach?></div></main></div><?php require __DIR__.'/../layouts/foot.php';?>